mapper.select:
select apt_cmplex_no
from mgmt_office
where mgmt_ofc_no = #{mgmtOfcNo}

select mh.meter_hstry_no , mh.facility_no , f.facility_nm , f.facility_ty_cd , fac_ty.code_name as facility_ty_nm , mh.ho_no , mh.meter_dt , mh.pre_val , mh.curr_val , mh.meter_cn , mh.meter_rslt_cd , rslt.code_name as meter_rslt_nm , mh.reg_dt , mh.mdf_dt , up.utility_provider_no , up.csv_idntf_key , up.ext_cust_no , p.partner_no , p.partner_nm from meter_hstry mh left join facility f on mh.facility_no = f.facility_no left join common_code fac_ty on f.facility_ty_cd = fac_ty.code_no_cd and fac_ty.group_code_no = 'FACILITY_TY' left join utility_provider up on mh.utility_provider_no = up.utility_provider_no left join partner p on up.partner_no = p.partner_no left join common_code rslt on mh.meter_rslt_cd = rslt.code_no_cd and rslt.group_code_no = 'METER_RSLT' where up.apt_cmplex_no = #{aptCmplexNo}
and up.utility_provider_no = #{utilityProviderNo}
and mh.meter_rslt_cd = #{meterRsltCd}
and mh.meter_dt >= to_date(#{startDt}, 'yyyy-mm-dd')
and mh.meter_dt < to_date(#{endDt}, 'yyyy-mm-dd') + 1
and ( lower(f.facility_nm) like '%' || lower(#{keyword}) || '%' or lower(mh.facility_no) like '%' || lower(#{keyword}) || '%' or lower(mh.ho_no) like '%' || lower(#{keyword}) || '%' or lower(mh.meter_cn) like '%' || lower(#{keyword}) || '%' or lower(p.partner_nm) like '%' || lower(#{keyword}) || '%' )
order by mh.meter_dt desc , mh.meter_hstry_no desc

select count(*)
from facility
where apt_cmplex_no = #{aptCmplexNo}
and facility_no = #{facilityNo}

mapper.insert:
insert into meter_upload_hstry (
meter_upload_hstry_no
, utility_provider_no
, apt_cmplex_no
, file_group_no
, upload_dt
, upload_user_no
, total_cnt
, upload_stts_cd
, err_cn
, rmrk_cn
) values (
#{meterUploadHstryNo}
, #{utilityProviderNo}
, #{aptCmplexNo}
, #{fileGroupNo}
, sysdate
, #{uploadUserNo}
, #{totalCnt}
, #{uploadSttsCd}
, #{errCn}
, #{rmrkCn}
)

insert into meter_hstry (
meter_hstry_no
, facility_no
, ho_no
, meter_dt
, pre_val
, curr_val
, meter_cn
, meter_rslt_cd
, reg_dt
, utility_provider_no
) values (
'MTR' || lpad(seq_meter_hstry.nextval, 6, '0')
, #{facilityNo}
, #{hoNo}
, #{meterDt}
, #{preVal}
, #{currVal}
, #{meterCn}
, #{meterRsltCd}
, sysdate
, #{utilityProviderNo}
)
